mapper.update:
update contenuti set

            embedding = #{embeddingString},

        data_indicizzazione = NOW(),
        esito_indicizzazione = #{esito}
where
    id = #{contenuto.id}

mapper.select:
select id, id_contenuto as idContenuto, tipo_contenuto as tipoContenuto, titolo, autore, materia, data, embedding, data_indicizzazione as dataIndicizzazione, esito_indicizzazione as esitoIndicizzazione, testo, data_inserimento as dataInserimento, data_cancellazione as dataCancellazione, stato from contenuti c
1=1
and c.id = #{id}
and c.tipo_contenuto = #{tipoContenuto}
and c.id_contenuto = #{idContenuto}
and c.embedding = ''
and esito_indicizzazione != 'OK'
and stato = #{stato}
order by data_indicizzazione
